import TrackItem from '../../src/components/TrackItem'
import type { RecentTrack } from '../../src/types/recent-track'

const track: RecentTrack = {
  id: 'track-1',
  name: 'Golden Hour',
  artists: ['Juniper Lane', 'Mira Sol'],
  durationMs: 217_000,
  albumImageUrl:
    "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' fill='%2380576f'/%3E%3C/svg%3E",
  playedAt: '2026-10-13T12:42:00.000Z',
}

describe('recent listening track', () => {
  it('rendering a track → shows its artwork and listening details', () => {
    cy.viewport(1280, 720)
    cy.mount(<TrackItem track={track} />)

    cy.get('[data-testid="recent-track"]').within(() => {
      cy.contains('h4', 'Golden Hour')
      cy.contains('Juniper Lane, Mira Sol')
      cy.contains('3:37')
      cy.get('time').should('have.attr', 'datetime', track.playedAt)
      cy.get('img')
        .should('have.attr', 'alt', 'Golden Hour album cover')
        .and(($image) => {
          expect(($image[0] as HTMLImageElement).naturalWidth).to.be.greaterThan(
            0,
          )
        })
    })
    cy.get('[data-testid="recent-track"]').matchImage()
  })
})
